insert into public.categories (id, name, telugu_name, slug, parent_id, description, theme_default, display_order) values
  ('10000000-0000-4000-8000-000000000001', '1 Gram Gold Jewellery', 'ఒక గ్రాము బంగారు ఆభరణాలు', '1-gram-gold-jewellery', null, 'Micro gold plated temple, Kempu and bridal jewellery with the authentic look of 22K gold.', 'heritage', 1),
  ('10000000-0000-4000-8000-000000000002', 'Vaddanam & Hip Belts', 'వడ్డాణాలు', 'vaddanam-hip-belts', '10000000-0000-4000-8000-000000000001', 'Nakshi, Kempu and Lakshmi vaddanams sized for every saree drape.', 'heritage', 2),
  ('10000000-0000-4000-8000-000000000003', 'Nallapusalu & Black Beads', 'నల్లపూసలు', 'nallapusalu-black-beads', '10000000-0000-4000-8000-000000000001', 'Traditional nallapusalu chains with gold beads, kasulu and Lakshmi pendants.', 'heritage', 3),
  ('10000000-0000-4000-8000-000000000004', 'Choker Sets', 'చోకర్ సెట్లు', 'choker-sets', '10000000-0000-4000-8000-000000000001', 'Bridal and festive chokers with matching jhumkas.', 'heritage', 4),
  ('10000000-0000-4000-8000-000000000005', 'Anti-Tarnish Waterproof Jewellery', 'యాంటీ-టార్నిష్ వాటర్‌ప్రూఫ్ ఆభరణాలు', 'anti-tarnish-waterproof-jewellery', null, 'PVD-coated 316L stainless steel jewellery that survives showers, sweat and everyday life.', 'modern', 5),
  ('10000000-0000-4000-8000-000000000006', 'American Diamond & CZ Sets', 'అమెరికన్ డైమండ్ & CZ సెట్లు', 'american-diamond-cz-sets', null, 'AAA grade Swiss CZ necklace sets and rings with real-diamond sparkle.', 'heritage', 6),
  ('10000000-0000-4000-8000-000000000007', 'Korean Fashion Accessories', 'కొరియన్ ఫ్యాషన్ యాక్సెసరీస్', 'korean-fashion-accessories', null, 'Dainty K-trend earrings, pearls and pendants for college and office.', 'modern', 7)
insert into public.products (id, title, telugu_title, slug, description, category_id, mrp, sale_price, jewellery_type, plating_type, warranty_details, available_sizes, stock_count, featured) values
  ('20000000-0000-4000-8000-000000000001', 'Lakshmi Nakshi Temple Vaddanam', 'లక్ష్మీ నక్షి టెంపుల్ వడ్డాణం', 'lakshmi-nakshi-temple-vaddanam', 'A hand-finished Nakshi temple vaddanam with a central Goddess Lakshmi medallion, intricate peacock carvings and a flexible link band that sits flat on silk sarees. Made for weddings, Varalakshmi Vratham and Seemantham — the authentic look of a 22K heirloom at a fraction of the cost.', '10000000-0000-4000-8000-000000000002', 6499, 3899, 'nakshi-temple', 'Micro Gold Plated (Antique Nakshi Finish)', '1-Year Re-polishing Guarantee', array['28', '30', '32', '34', '36', '38']::text[], 8, true),
  ('20000000-0000-4000-8000-000000000002', 'Peacock Kempu Stone Hip Belt', 'నెమలి కెంపు రాళ్ళ వడ్డాణం', 'peacock-kempu-stone-hip-belt', 'A lightweight hip belt studded with ruby-red Kempu stones and twin peacock motifs. The adjustable hook fits waists from 26 to 40 inches, making it a perfect gift for half-saree functions and bridal trousseaus.', '10000000-0000-4000-8000-000000000002', 4999, 2999, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['Adjustable']::text[], 12, false),
  ('20000000-0000-4000-8000-000000000003', 'Lakshmi Coin Nallapusalu Long Chain', 'లక్ష్మీ కాసుల నల్లపూసల గొలుసు', 'lakshmi-coin-nallapusalu-long-chain', 'Traditional double-line nallapusalu with glossy black beads, gold spacer balls and a pair of Lakshmi kasulu at the centre. Designed for daily wear by newly-weds who want the auspicious look without risking real gold.', '10000000-0000-4000-8000-000000000003', 2799, 1699, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['24 inch', '30 inch']::text[], 20, true),
  ('20000000-0000-4000-8000-000000000004', 'Traditional Gold Bead Nallapusalu', 'సాంప్రదాయ బంగారు పూసల నల్లపూసలు', 'traditional-gold-bead-nallapusalu', 'A short single-line nallapusalu with alternating gold beads — comfortable enough for office and elegant enough for poojas. Pairs beautifully with a mangalsutra pendant.', '10000000-0000-4000-8000-000000000003', 1999, 1199, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['18 inch', '24 inch']::text[], 25, false),
  ('20000000-0000-4000-8000-000000000005', 'Nakshi Lakshmi Choker Set with Jhumkas', 'నక్షి లక్ష్మీ చోకర్ సెట్ & జుంకాలు', 'nakshi-lakshmi-choker-set-jhumkas', 'An antique Nakshi choker with Lakshmi engravings, pearl drops and matching temple jhumkas. Adjustable dori at the back so it sits perfectly with blouses of any neckline.', '10000000-0000-4000-8000-000000000004', 5999, 3499, 'nakshi-temple', 'Micro Gold Plated (Antique Nakshi Finish)', '1-Year Re-polishing Guarantee', array['Adjustable']::text[], 10, true),
  ('20000000-0000-4000-8000-000000000006', 'Kempu & Emerald Bridal Choker Set', 'కెంపు & పచ్చ బ్రైడల్ చోకర్ సెట్', 'kempu-emerald-bridal-choker-set', 'Ruby-red Kempu and emerald-green stones set in a broad bridal choker with a matching pair of chandbali earrings. Our bestseller for Pellikuthuru and reception looks.', '10000000-0000-4000-8000-000000000004', 4499, 2799, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['Adjustable']::text[], 9, true),
  ('20000000-0000-4000-8000-000000000007', 'Micro Gold Plated Bangles (Set of 4)', 'మైక్రో గోల్డ్ గాజులు (4 సెట్)', 'micro-gold-plated-bangles-set-of-4', 'Four slim bangles with diamond-cut Nakshi patterns that catch the light with every movement. Stack them with glass bangles for festivals or wear two for everyday elegance.', '10000000-0000-4000-8000-000000000001', 2499, 1499, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['2.4', '2.6', '2.8']::text[], 30, true),
  ('20000000-0000-4000-8000-000000000008', 'Guttapusalu Long Haram', 'గుత్తపూసల పొడవాటి హారం', 'guttapusalu-long-haram', 'A statement guttapusalu haram with clusters of pearl and gold beads cascading from a Kempu-studded mango mala. The centrepiece of any bridal jewellery set.', '10000000-0000-4000-8000-000000000001', 7499, 4499, '1-gram-gold', 'Micro Gold Plated', '1-Year Re-polishing Guarantee', array['Adjustable']::text[], 6, false),
  ('20000000-0000-4000-8000-000000000009', 'AAA Swiss CZ Bridal Necklace Set', 'అమెరికన్ డైమండ్ బ్రైడల్ నెక్లెస్ సెట్', 'aaa-swiss-cz-bridal-necklace-set', 'Hand-set AAA grade Swiss cubic zirconia in a rhodium-plated necklace with matching earrings. Real-diamond fire for receptions, engagements and sangeet nights.', '10000000-0000-4000-8000-000000000006', 5499, 3299, 'american-diamond', 'Rhodium', '6-Month Stone & Plating Guarantee', array['Adjustable']::text[], 7, true),
  ('20000000-0000-4000-8000-000000000010', 'Rose Gold CZ Cocktail Ring', 'రోజ్ గోల్డ్ CZ కాక్‌టెయిల్ ఉంగరం', 'rose-gold-cz-cocktail-ring', 'A halo cocktail ring with a brilliant-cut AAA CZ centre stone in a soft rose gold finish. The open band adjusts to fit most fingers.', '10000000-0000-4000-8000-000000000006', 1299, 749, 'american-diamond', 'Rose Gold Plated', '6-Month Stone & Plating Guarantee', array['Adjustable']::text[], 18, false),
  ('20000000-0000-4000-8000-000000000011', 'Waterproof PVD Gold Paperclip Chain', 'వాటర్‌ప్రూఫ్ PVD గోల్డ్ పేపర్‌క్లిప్ చైన్', 'waterproof-pvd-gold-paperclip-chain', 'A sleek paperclip chain in 316L surgical stainless steel with 18K gold-tone PVD coating. Shower-proof, sweat-proof and hypoallergenic — wear it to the gym, the office and the beach at RK Beach without a second thought.', '10000000-0000-4000-8000-000000000005', 1499, 899, 'anti-tarnish', 'PVD 316L Stainless Steel (18K Gold Tone)', '1-Year Colour Warranty', array['16 inch', '18 inch']::text[], 40, true),
  ('20000000-0000-4000-8000-000000000012', 'Anti-Tarnish Butterfly Huggie Earrings', 'యాంటీ-టార్నిష్ బటర్‌ఫ్లై హగ్గీ చెవిపోగులు', 'anti-tarnish-butterfly-huggie-earrings', 'Chunky everyday huggies with a tiny butterfly charm. 316L steel with PVD gold — no green ears, no fading, no fuss.', '10000000-0000-4000-8000-000000000005', 999, 599, 'anti-tarnish', 'PVD 316L Stainless Steel', '1-Year Colour Warranty', array[]::text[], 35, true),
  ('20000000-0000-4000-8000-000000000013', 'Minimal PVD Office-Wear Bracelet', 'మినిమల్ PVD ఆఫీస్ వేర్ బ్రేస్‌లెట్', 'minimal-pvd-office-wear-bracelet', 'A slim cuff-style bracelet with a single CZ accent, built for long days at HITEC City desks. Waterproof PVD coating keeps the shine through hand-washes and sanitiser.', '10000000-0000-4000-8000-000000000005', 1199, 699, 'anti-tarnish', 'PVD 316L Stainless Steel', '1-Year Colour Warranty', array['Adjustable']::text[], 22, false),
  ('20000000-0000-4000-8000-000000000014', 'Korean Pearl Drop Earrings', 'కొరియన్ ముత్యాల డ్రాప్ చెవిపోగులు', 'korean-pearl-drop-earrings', 'Featherlight freshwater-look pearl drops on gold-tone hooks — the K-drama staple that goes from college to cafe to sangeet.', '10000000-0000-4000-8000-000000000007', 799, 449, 'korean', '14K Gold Plated Brass, Nickel-Free', '6-Month Plating Warranty', array[]::text[], 50, true),
  ('20000000-0000-4000-8000-000000000015', 'K-Trend Heart Pendant Necklace', 'K-ట్రెండ్ హార్ట్ పెండెంట్ నెక్లెస్', 'k-trend-heart-pendant-necklace', 'A puffed heart pendant on a fine anti-tarnish chain, inspired by Tollywood and K-pop street style. Layer it or wear it solo.', '10000000-0000-4000-8000-000000000007', 899, 499, 'korean', '14K Gold Plated, Anti-Tarnish Coated', '6-Month Plating Warranty', array['Adjustable']::text[], 28, false)
